html:
{% set os_doc = frappe.get_doc("IB Order Sheet", doc.order_sheet) if doc.order_sheet else None %}
{% set so_name = os_doc.sales_order if os_doc else None %}
{% set dims = frappe.db.get_value("Sales Order Item", {"parent": so_name, "item_code": doc.item_code}, ["color", "width_mm", "length_mtr", "qty_pkg", "total_pkg"], as_dict=True) if so_name else None %}
{% set jr = frappe.get_doc("IB Jumbo Roll", doc.jumbo_roll) if doc.jumbo_roll else None %}
{% set machine_name = frappe.db.get_value("IB Machine", doc.machine, "machine_name") if doc.machine else None %}
<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #111; padding: 10px; }
  .print-format { margin-top: 0mm; margin-right: 0mm; margin-bottom: 0mm; margin-left: 0mm; }
  .jo-header { text-align: center; margin-bottom: 10px; }
  .jo-header img { width: 100%; max-height: 60px; object-fit: contain; display: block; margin: 0 auto 6px; }
  .jo-header h2 { margin: 4px 0 0; font-size: 20px; letter-spacing: 1px; }
  .jo-wo-name { text-align: center; font-size: 15px; font-weight: bold; margin-bottom: 14px; }
  .jo-wo-box { border: 2px solid #d97757; padding: 6px 16px; display: inline-block; }
  table.jo-meta { width: 100%; table-layout: fixed; border-collapse: separate; border-spacing: 0; margin-bottom: 14px; }
  table.jo-meta td { padding: 5px 8px; vertical-align: top; border: none; border-bottom: 1px solid #eee; background: none; }
  table.jo-meta td.label { font-weight: bold; color: #444; }
  table.jo-meta td.value { }
  table.jo-meta col.jo-label-col { width: 160px; }
  table.jo-meta col.jo-value-col { width: auto; }
  .jo-section-title { font-weight: bold; font-size: 12px; text-transform: uppercase; color: #d97757;
                       border-bottom: 1px solid #d97757; margin: 16px 0 6px; padding-bottom: 2px; }
  .jo-qty-block { text-align: center; margin: 16px 0; }
  .jo-qty-block .jo-qty-val { font-size: 26px; font-weight: bold; }
  .jo-qty-block .jo-qty-uom { font-size: 14px; color: #555; }
  .jo-make-line { text-align: center; font-size: 15px; font-weight: bold; margin: 8px 0 4px;
                  background: #fdf1ec; padding: 6px; border: 1px dashed #d97757; }
  .jo-footer { margin-top: 30px; width: 100%; }
  .jo-footer td { padding: 4px; }
  .sig-line { border-top: 1px solid #444; padding-top: 4px; text-align: center; font-size: 10px; color: #555; }
</style>

<div class="jo-header">
  <img src="/files/Instabiz_LH_v2.png">
  <h2>JOB ORDER</h2>
</div>

<div class="jo-wo-name">
  <span class="jo-wo-box">WO No: {{ doc.name }}</span>
</div>

<table class="jo-meta">
  <tr><td class="label">Item Code</td><td class="value">{{ doc.item_code }}</td></tr>
  <tr><td class="label">Item Name</td><td class="value">{{ doc.item_name or "" }}</td></tr>
  <tr><td class="label">Stage</td><td class="value">{{ doc.stage }}</td></tr>
  {% if doc.machine %}
  <tr><td class="label">Machine</td><td class="value">{{ doc.machine }}{% if machine_name %} — {{ machine_name }}{% endif %}</td></tr>
  {% endif %}
  {% if doc.priority %}
  <tr><td class="label">Priority</td><td class="value">{{ doc.priority }}</td></tr>
  {% endif %}
</table>

{% if dims and (dims.color or dims.width_mm or dims.length_mtr or dims.qty_pkg or dims.total_pkg) %}
<div class="jo-section-title">Dimensions</div>
<table class="jo-meta">
  {% if dims.color %}
  <tr><td class="label">Color</td><td class="value">{{ dims.color }}</td></tr>
  {% endif %}
  {% if dims.width_mm %}
  <tr><td class="label">Width (MM)</td><td class="value">{{ dims.width_mm }}</td></tr>
  {% endif %}
  {% if dims.length_mtr %}
  <tr><td class="label">Length (MTR)</td><td class="value">{{ dims.length_mtr }}</td></tr>
  {% endif %}
  {% if dims.qty_pkg %}
  <tr><td class="label">Qty/Pkg</td><td class="value">{{ dims.qty_pkg }}</td></tr>
  {% endif %}
  {% if dims.total_pkg %}
  <tr><td class="label">Total Pkg</td><td class="value">{{ dims.total_pkg }}</td></tr>
  {% endif %}
</table>
{% endif %}

<div class="jo-qty-block">
  <div class="jo-qty-val">{{ doc.target_qty or 0 }}</div>
  <div class="jo-qty-uom">{{ doc.target_uom or "" }}</div>
</div>

{% if doc.target_uom == "PCS" and doc.pcs_to_make %}
<div class="jo-make-line">Pieces to Make: {{ doc.pcs_to_make }}</div>
{% elif doc.target_uom == "SQMT" and doc.logs_to_make %}
<div class="jo-make-line">Logs to Make: {{ doc.logs_to_make }}</div>
{% endif %}

{% if jr %}
<div class="jo-section-title">Jumbo Roll</div>
<table class="jo-meta">
  {% if jr.width_mm %}
  <tr><td class="label">Jumbo Size (Width MM)</td><td class="value">{{ jr.width_mm }}</td></tr>
  {% endif %}
  {% if jr.length_mtr %}
  <tr><td class="label">Jumbo Length (MTR)</td><td class="value">{{ jr.length_mtr }}</td></tr>
  {% endif %}
</table>
{% endif %}

{% if doc.notes %}
<div class="jo-section-title">Notes</div>
<div>{{ doc.notes }}</div>
{% endif %}

<table class="jo-footer">
  <tr>
    <td style="width:33%"><div class="sig-line">Operator Signature</div></td>
    <td style="width:33%"><div class="sig-line">Actual Output Qty / Date</div></td>
    <td style="width:33%"><div class="sig-line">Checked By</div></td>
  </tr>
</table>
